begin;set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table prova_fase(actor uuid,azienda uuid,sub uuid,ordine uuid,fase uuid,altra_fase uuid,evidenza uuid);
insert into prova_fase select sp.user_id,sp.company_id,s.id,o.id,gen_random_uuid(),gen_random_uuid(),gen_random_uuid() from public.staff_permissions sp join public.subappaltatori_sicurezza s on s.company_id=sp.company_id join public.orders o on o.company_id=sp.company_id where sp.can_view_sicurezza_cantiere and not sp.sola_lettura limit 1;
grant select on prova_fase to authenticated;
do $$begin if not exists(select 1 from prova_fase) then raise exception 'Fixture non disponibile';end if;end$$;
insert into public.order_work_phases(id,company_id,order_id,name,position,start_date,end_date) select fase,azienda,ordine,'TEST FASE ROLLBACK',999,'2026-11-01','2026-11-30' from prova_fase;
insert into public.order_work_phases(id,company_id,order_id,name,position) select f.altra_fase,o.company_id,o.id,'TEST ALTRA AZIENDA',999 from prova_fase f cross join lateral(select company_id,id from public.orders where company_id<>f.azienda limit 1)o;
do $$declare f record;begin select * into f from prova_fase;
 begin insert into public.sicurezza_fascicolo(company_id,subappaltatore_id,order_id,fase_id,tipo,titolo) values(f.azienda,f.sub,f.ordine,f.altra_fase,'pos','TEST FASE ESTRANEA');raise exception 'ASSERT: fase estranea accettata';exception when raise_exception then if sqlerrm not like 'La fase non appartiene%' then raise;end if;end;
 begin insert into public.sicurezza_fascicolo(company_id,subappaltatore_id,order_id,applicabile_dal,applicabile_al,tipo,titolo) values(f.azienda,f.sub,f.ordine,'2026-11-20','2026-11-01','pos','TEST PERIODO INVERSO');raise exception 'ASSERT: periodo inverso accettato';exception when check_violation then null;end;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_fase;set local role authenticated;
insert into public.sicurezza_fascicolo(id,company_id,subappaltatore_id,order_id,fase_id,applicabile_dal,applicabile_al,tipo,titolo,catalogo_id,catalogo_versione) select evidenza,azienda,sub,ordine,fase,'2026-11-02','2026-11-20','pos','TEST REQUISITO FASE','pos',1 from prova_fase;
reset role;
-- Moving planning dates must not silently move an explicit requirement interval.
update public.order_work_phases set start_date='2026-12-01',end_date='2026-12-30' where id=(select fase from prova_fase);
do $$declare f record;begin select * into f from prova_fase;
 if not exists(select 1 from public.sicurezza_fascicolo where id=f.evidenza and applicabile_dal='2026-11-02' and applicabile_al='2026-11-20' and data_scadenza is null) then raise exception 'ASSERT: periodo copiato dal calendario';end if;
 begin delete from public.order_work_phases where id=f.fase;raise exception 'ASSERT: fase con requisiti eliminata';exception when raise_exception then if sqlerrm not like 'La fase ha requisiti di sicurezza collegati%' then raise;end if;end;
end$$;
insert into storage.objects(bucket_id,name) select 'fascicoli-cantiere',azienda::text||'/'||evidenza::text||'/sintetico.pdf' from prova_fase;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_fase;set local role authenticated;
update public.sicurezza_fascicolo e set file_path=f.azienda::text||'/'||f.evidenza::text||'/sintetico.pdf',stato='verificato' from prova_fase f where e.id=f.evidenza;
do $$declare f record;begin select * into f from prova_fase;
 begin update public.sicurezza_fascicolo set applicabile_al='2026-12-31' where id=f.evidenza;raise exception 'ASSERT: periodo verificato cambiato';exception when raise_exception then if sqlerrm not like 'Riapri in integrazione%' then raise;end if;end;
end$$;
reset role;
select 'PASS: fase, azienda, periodo, verifica, ripianificazione e conservazione storico' as esito;
rollback;
